window.VeilGardeData.files["Tests-VeilGardeTrainingTests"] = {"group":"Tests-VeilGardeTrainingTests","files":[{"path":"Tests/VeilGardeTrainingTests/BackboneTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,121]],"header":{"lines":[1,11],"target":"VeilGardeTrainingTests","what":[6,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1719,"scopes":[["E","Backbone",null,"",19,19,[19,14],40,null,-1,0,"a",[]],["v","checkpoint",null,"static",21,21,[21,32],33,[20,20],0,0,"a"],["f","shipped",["_"],"static",36,36,[36,52],39,[35,35],0,0,"a"],["S","BackboneTests",null,"",42,43,[43,21],105,null,-1,0,"a"],["f","bicubic",[],"",44,45,[45,26],57,null,3,0,"a"],["f","renames",[],"",59,60,[60,19],66,null,3,0,"a"],["f","bake",[],"",68,69,[69,23],82,null,3,0,"a"],["f","importMatchesTheShippedFiles",[],"",84,85,[85,47],104,null,3,0,"a"],["X","TrainingMLXSuites",null,"",107,107,[107,28],121,null,-1,0,"a"],["S","BackboneOnGPU",null,"",108,109,[109,25],120,null,8,0,"a"],["f","xxsmall",[],"",112,112,[112,30],119,null,9,0,"a"]],"old":"","new":"//\n//  BackboneTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The DINOv2 import from Hugging Face's checkpoint: the bicubic resize equals PyTorch's\n//        bit for bit (bicubic_fixture.json); the rename map covers Dinov2ViT's 222 tensors; and,\n//        when this Mac has the checkpoint and the shipped files, small is byte-identical to the\n//        file Python exported, xsmall's tensors are byte-identical to Garde's, and (on the GPU)\n//        xxsmall's quantized tensors are byte-identical to Garde's.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\nimport VeilGardeLens\n@testable import VeilGardeTraining\n\nenum Backbone {\n    /// The checkpoint the T9's hf/ cache holds (downloaded once with Python's hub client).\n    static var checkpoint: URL? {\n        let env = ProcessInfo.processInfo.environment\n        var candidates: [URL] = []\n        if let named = env[\"VEILGARDE_DINOV2_CHECKPOINT\"] { candidates.append(URL(fileURLWithPath: named)) }\n        if let area = WorkArea.resolve() {\n            let snapshots = area.root.appendingPathComponent(\"hf/hub/models--facebook--dinov2-small/snapshots\", isDirectory: true)\n            for name in (try? FileManager.default.contentsOfDirectory(atPath: snapshots.path))?.sorted() ?? [] {\n                candidates.append(snapshots.appendingPathComponent(\"\\(name)/model.safetensors\"))\n            }\n            candidates.append(area.root.appendingPathComponent(\"hf/models/facebook/dinov2-small/model.safetensors\"))\n        }\n        return candidates.first { FileManager.default.fileExists(atPath: $0.path) }\n    }\n\n    /// A shipped weight file, when this Mac has it.\n    static func shipped(_ file: WeightFile) -> URL? {\n        if let area = WorkArea.resolve() { WeightLocator.shared.register(area.weights) }\n        return WeightLocator.shared.url(file)\n    }\n}\n\n@Suite(\"Backbone: DINOv2 from Hugging Face's checkpoint\")\nstruct BackboneTests {\n    @Test(\"the bicubic resize is PyTorch's, bit for bit\")\n    func bicubic() throws {\n        let fixture = try Fixture.json(\"bicubic_fixture.json\")\n        let cases = fixture[\"cases\"] as! [[String: Any]]\n        #expect(cases.count == 3)\n        for c in cases {\n            let planes = Int(double(c[\"channels\"])), input = Int(double(c[\"in\"])), output = Int(double(c[\"out\"]))\n            let y = TorchBicubic.resize(floats(c[\"x\"]), planes: planes, input: input, output: output)\n            let expected = floats(c[\"y\"])\n            #expect(y.count == expected.count)\n            let differing = zip(y, expected).filter { $0.0.bitPattern != $0.1.bitPattern }.count\n            #expect(differing == 0, \"\\(input)→\\(output): \\(differing) of \\(y.count) values differ from torch\")\n        }\n    }\n\n    @Test(\"the rename map covers Dinov2ViT's tensors once each\")\n    func renames() {\n        let names = Dinov2Import.renames().map(\\.mlx) + [\"patch_embed.weight\", \"pos_embed\"]\n        #expect(names.count == 222)\n        #expect(Set(names).count == 222)\n        #expect(Set(Dinov2Import.renames().map(\\.hf)).count == 220)\n        #expect(names.contains(\"blocks.11.mlp.fc2.weight\") && names.contains(\"cls_token\") && names.contains(\"norm.bias\"))\n    }\n\n    @Test(\"the position bake keeps the CLS row and resizes the grid\")\n    func bake() throws {\n        // A 3×3 grid of 2 channels → 2×2, against the resize run directly.\n        let dim = 2, side = 3\n        var values: [Float] = [9, -9]\n        for p in 0..<(side * side) { for c in 0..<dim { values.append(Float(p * 10 + c)) } }\n        let baked = try Dinov2Import.bake(values, shape: [1, 1 + side * side, dim], to: 2)\n        #expect(baked.shape == [1, 5, 2])\n        #expect(Array(baked.values.prefix(2)) == [9, -9])\n        var planes = [Float](repeating: 0, count: dim * side * side)\n        for p in 0..<(side * side) { for c in 0..<dim { planes[c * side * side + p] = values[(1 + p) * dim + c] } }\n        let direct = TorchBicubic.resize(planes, planes: dim, input: side, output: 2)\n        for p in 0..<4 { for c in 0..<dim { #expect(baked.values[(1 + p) * dim + c] == direct[c * 4 + p]) } }\n        #expect(throws: VeilGardeFailure.self) { try Dinov2Import.bake(values, shape: [1, 9, dim]) }\n    }\n\n    @Test(\"small is byte-identical to the shipped export; xsmall's tensors are Garde's\", .enabled(if: Backbone.checkpoint != nil))\n    func importMatchesTheShippedFiles() throws {\n        let checkpoint = try #require(Backbone.checkpoint)\n        let tensors = try Dinov2Import.convert(try SafetensorsFile(url: checkpoint))\n        #expect(tensors.count == 222)\n        #expect(tensors[\"pos_embed\"]?.shape == [1, 257, 384])\n        #expect(tensors[\"patch_embed.weight\"]?.shape == [384, 14, 14, 3])\n        if let small = Backbone.shipped(.dinov2Small) {\n            let data = try Dinov2Import.encodeSmall(tensors)\n            let comparison = try Dinov2Import.compare(try SafetensorsFile(data: data), to: SafetensorsFile(url: small), referenceName: small.path)\n            #expect(comparison.problems.isEmpty, \"\\(comparison.problems)\")\n            #expect(comparison.identicalBytes == 222, \"max |Δ| \\(comparison.maxAbsDifference) at \\(comparison.worst ?? \"?\")\")\n            #expect(comparison.sameFile, \"the file is not byte-identical to \\(small.path)\")\n        }\n        if let xsmall = Backbone.shipped(.dinov2XSmall) {\n            let data = try Dinov2Import.encodeXSmall(tensors)\n            let comparison = try Dinov2Import.compare(try SafetensorsFile(data: data), to: SafetensorsFile(url: xsmall), referenceName: xsmall.path)\n            #expect(comparison.problems.isEmpty, \"\\(comparison.problems)\")\n            #expect(comparison.identicalBytes == 222, \"max |Δ| \\(comparison.maxAbsDifference) at \\(comparison.worst ?? \"?\")\")\n        }\n    }\n}\n\nextension TrainingMLXSuites {\n    @Suite(\"Backbone on the GPU\", .serialized)\n    struct BackboneOnGPU {\n        @Test(\"xxsmall quantized from xsmall is Garde's, tensor for tensor\",\n              .enabled(if: Backbone.shipped(.dinov2XSmall) != nil && Backbone.shipped(.dinov2XXSmall) != nil))\n        func xxsmall() throws {\n            let xsmall = try #require(Backbone.shipped(.dinov2XSmall)), reference = try #require(Backbone.shipped(.dinov2XXSmall))\n            let data = try Dinov2Import.encodeXXSmall(fromXSmall: xsmall)\n            let comparison = try Dinov2Import.compare(try SafetensorsFile(data: data), to: SafetensorsFile(url: reference), referenceName: reference.path)\n            #expect(comparison.tensors == 366)\n            #expect(comparison.problems.isEmpty, \"\\(comparison.problems.prefix(4))\")\n            #expect(comparison.identicalBytes == 366, \"max |Δ| \\(comparison.maxAbsDifference) at \\(comparison.worst ?? \"?\")\")\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/BoostTrainerTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,154]],"header":{"lines":[1,12],"target":"VeilGardeTrainingTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1730,"scopes":[["S","BoostTrainerTests",null,"",20,21,[21,25],154,null,-1,0,"a"],["f","exactData",[],"static",22,22,[22,107],28,null,0,0,"a"],["f","exact",["_"],"",30,31,[31,38],69,null,0,0,"a"],["f","histData",[],"static",71,71,[71,109],76,null,0,0,"a"],["f","hist",[],"",78,79,[79,23],95,null,0,0,"a"],["f","warmStart",[],"",97,98,[98,28],114,null,0,0,"a"],["f","earlyStopping",[],"",116,117,[117,32],127,null,0,0,"a"],["f","frigateReadsIt",[],"",129,130,[130,33],145,null,0,0,"a"],["f","baseScore",[],"",147,148,[148,28],153,null,0,0,"a"]],"old":"","new":"//\n//  BoostTrainerTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The native trainer against xgboost 3.2. On integer features (so the bins are the values\n//        themselves) it grows XGBoost's trees: the same splits, children and node order, leaves\n//        and gains within float rounding, with weights, scale_pos_weight, γ, λ and\n//        min_child_weight. On continuous data it lands within ±0.005 AUC and ±0.01 log loss of\n//        xgboost's model, a warm start continues a model xgboost wrote without touching its\n//        trees, and every model it writes reads back through Frigate's evaluator unchanged.\n//\n\nimport Foundation\nimport Frigate\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"GBDT trainer\")\nstruct BoostTrainerTests {\n    static func exactData() throws -> (fixture: [String: Any], data: BoostDataset, weighted: BoostDataset) {\n        let fixture = try Fixture.json(\"boost_exact.json\")\n        let rows = fixture[\"X\"] as! [[NSNumber]]\n        let x = rows.flatMap { $0.map(\\.floatValue) }\n        let y = floats(fixture[\"y\"]), w = floats(fixture[\"w\"])\n        return (fixture, BoostDataset(x: x, y: y, features: 4), BoostDataset(x: x, y: y, weight: w, features: 4))\n    }\n\n    @Test(\"integer features: xgboost's trees, node for node\", arguments: [\"plain\", \"weighted_spw\", \"gamma_mcw_lambda\"])\n    func exact(_ name: String) throws {\n        let (fixture, plain, weighted) = try Self.exactData()\n        let c = (fixture[\"cases\"] as! [[String: Any]]).first { $0[\"name\"] as! String == name }!\n        let p = c[\"params\"] as! [String: Any]\n        var params = BoostParams(trees: c[\"rounds\"] as! Int, maxDepth: p[\"max_depth\"] as! Int, eta: double(p[\"eta\"]))\n        if let v = p[\"base_score\"] { params.baseScore = double(v) }\n        if let v = p[\"scale_pos_weight\"] { params.scalePosWeight = double(v) }\n        if let v = p[\"gamma\"] { params.gamma = double(v) }\n        if let v = p[\"min_child_weight\"] { params.minChildWeight = double(v) }\n        if let v = p[\"lambda\"] { params.lambda = double(v) }\n        let data = (c[\"weighted\"] as! Bool) ? weighted : plain\n        let result = BoostTrainer.train(data, params: params)\n        let model = result.model\n\n        let expectedBase = GBDTModel(trees: [], baseScoreProbability: 0.5, featureCount: 4)\n        var stored = expectedBase; stored.baseScore = c[\"base_score\"] as! String\n        #expect(abs(model.baseScoreProbability - stored.baseScoreProbability) <= 1e-6, \"\\(name): base_score \\(model.baseScore) vs \\(stored.baseScore)\")\n\n        let trees = c[\"trees\"] as! [[String: Any]]\n        #expect(model.trees.count == trees.count)\n        for (k, (mine, theirs)) in zip(model.trees, trees).enumerated() {\n            #expect(mine.leftChildren.map(Int.init) == ints(theirs[\"left_children\"]), \"\\(name) tree \\(k): left\")\n            #expect(mine.rightChildren.map(Int.init) == ints(theirs[\"right_children\"]), \"\\(name) tree \\(k): right\")\n            #expect(mine.parents.map(Int.init) == ints(theirs[\"parents\"]), \"\\(name) tree \\(k): parents\")\n            #expect(mine.splitIndices.map(Int.init) == ints(theirs[\"split_indices\"]), \"\\(name) tree \\(k): split features\")\n            #expect(mine.defaultLeft == ints(theirs[\"default_left\"]), \"\\(name) tree \\(k): default_left\")\n            let conditions = floats(theirs[\"split_conditions\"]), weights = floats(theirs[\"base_weights\"])\n            let losses = floats(theirs[\"loss_changes\"]), hessians = floats(theirs[\"sum_hessian\"])\n            for i in 0..<min(mine.nodeCount, conditions.count) {\n                #expect(abs(mine.splitConditions[i] - conditions[i]) <= 1e-5 * max(1, abs(conditions[i])), \"\\(name) tree \\(k) node \\(i): condition\")\n                #expect(abs(mine.baseWeights[i] - weights[i]) <= 1e-5 * max(1, abs(weights[i])), \"\\(name) tree \\(k) node \\(i): weight\")\n                #expect(abs(mine.lossChanges[i] - losses[i]) <= 1e-4 * max(1, abs(losses[i])), \"\\(name) tree \\(k) node \\(i): loss change\")\n                #expect(abs(mine.sumHessian[i] - hessians[i]) <= 1e-4 * max(1, abs(hessians[i])), \"\\(name) tree \\(k) node \\(i): hessian\")\n            }\n        }\n        let margins = floats(c[\"margin\"])\n        let worst = (0..<data.count).map { abs(model.margin(data.row($0)) - margins[$0]) }.max() ?? 0\n        #expect(worst <= 1e-4, \"\\(name): margins differ by \\(worst)\")\n    }\n\n    static func histData() throws -> (train: BoostDataset, validation: BoostDataset, fixture: [String: Any]) {\n        let t = try Fixture.tensors(\"boost_hist.safetensors\")\n        return (BoostDataset(x: try t.float32(\"x_train\"), y: try t.float32(\"y_train\"), features: 8),\n                BoostDataset(x: try t.float32(\"x_val\"), y: try t.float32(\"y_val\"), features: 8),\n                try Fixture.json(\"boost_hist.json\"))\n    }\n\n    @Test(\"continuous features: within ±0.005 AUC and ±0.01 log loss of xgboost\")\n    func hist() throws {\n        let (train, validation, fixture) = try Self.histData()\n        let result = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 60, maxDepth: 4, eta: 0.1))\n        let p = (0..<validation.count).map { result.model.predict(validation.row($0)) }\n        let auc = Metrics.auc(p, validation.y), loss = Metrics.logloss(p, validation.y)\n        #expect(abs(auc - double(fixture[\"val_auc\"])) <= 0.005, \"AUC \\(auc) vs xgboost \\(double(fixture[\"val_auc\"]))\")\n        #expect(abs(loss - double(fixture[\"val_logloss\"])) <= 0.01, \"log loss \\(loss) vs xgboost \\(double(fixture[\"val_logloss\"]))\")\n        #expect(result.rounds.count == 60)\n        #expect(abs(result.rounds.last!.validation! - auc) < 1e-12)\n\n        let sampled = fixture[\"sampled\"] as! [String: Any]\n        let s = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 60, maxDepth: 4, eta: 0.1, subsample: 0.8, colsampleByTree: 0.75, seed: 3))\n        let ps = (0..<validation.count).map { s.model.predict(validation.row($0)) }\n        #expect(abs(Metrics.auc(ps, validation.y) - double(sampled[\"val_auc\"])) <= 0.01)\n        let again = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 60, maxDepth: 4, eta: 0.1, subsample: 0.8, colsampleByTree: 0.75, seed: 3))\n        #expect(again.model.encodeXGBoostJSON() == s.model.encodeXGBoostJSON(), \"a seed names one model\")\n    }\n\n    @Test(\"a warm start appends to xgboost's model and keeps its trees byte for byte\")\n    func warmStart() throws {\n        let (train, validation, fixture) = try Self.histData()\n        let warm = fixture[\"warm\"] as! [String: Any]\n        let text = warm[\"model30\"] as! String\n        let parent = try GBDTModel.decode(xgboostJSON: Data(text.utf8))\n        #expect(parent.trees.count == 30)\n        let result = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 10, maxDepth: 4, eta: 0.1), warmStart: parent)\n        #expect(result.model.trees.count == 40)\n        #expect(result.inheritedTrees == 30)\n        #expect(result.model.baseScore == parent.baseScore)\n        for i in 0..<30 { #expect(result.model.trees[i].raw == parent.trees[i].raw) }\n        #expect(Array(result.model.trees[30...].map(\\.id)) == Array(30..<40))\n        let encoded = String(decoding: result.model.encodeXGBoostJSON(), as: UTF8.self)\n        for tree in parent.trees { #expect(encoded.contains(tree.raw!)) }\n        let p = (0..<validation.count).map { result.model.predict(validation.row($0)) }\n        #expect(abs(Metrics.auc(p, validation.y) - double(warm[\"val_auc40\"])) <= 0.005)\n    }\n\n    @Test(\"early stopping keeps the best round and truncates to it\")\n    func earlyStopping() throws {\n        let (train, validation, _) = try Self.histData()\n        let result = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 400, maxDepth: 6, eta: 0.3, earlyStoppingRounds: 5))\n        let best = try #require(result.bestTreeCount)\n        #expect(result.model.trees.count == best)\n        #expect(result.rounds.count < 400)\n        let scores = result.rounds.compactMap(\\.validation)\n        let top = scores.max()!\n        #expect(abs(scores[best - 1] - top) < 1e-15)\n        #expect(scores.firstIndex(of: top)! == best - 1, \"the first best round wins\")\n    }\n\n    @Test(\"a trained model reads back through Frigate's evaluator with identical predictions\")\n    func frigateReadsIt() throws {\n        let (train, validation, _) = try Self.histData()\n        let result = BoostTrainer.train(train, params: BoostParams(trees: 25, maxDepth: 5, eta: 0.2, subsample: 0.9, colsampleByTree: 0.8, seed: 1))\n        let json = result.model.encodeXGBoostJSON()\n        let file = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-trained-\\(UUID().uuidString).json\")\n        try json.write(to: file)\n        defer { try? FileManager.default.removeItem(at: file) }\n        let frigate = try XGBoostTreeModel(url: file)\n        #expect(frigate.numFeatures == 8)\n        let decoded = try GBDTModel.decode(xgboostJSON: json)\n        #expect(decoded.encodeXGBoostJSON() == json, \"decode → encode is the identity on a trained model\")\n        for i in 0..<validation.count {\n            let row = validation.row(i)\n            #expect(frigate.predict(row) == result.model.predict(row))\n        }\n    }\n\n    @Test(\"base_score: the weighted mean at scale_pos_weight 1, a Newton step otherwise\")\n    func baseScore() throws {\n        let (_, plain, weighted) = try Self.exactData()\n        let mean = Double(zip(weighted.y, weighted.weight!).map { Double($0) * Double($1) }.reduce(0, +)) / weighted.weight!.map(Double.init).reduce(0, +)\n        #expect(abs(BoostTrainer.baseScore(weighted, scalePosWeight: 1) - mean) < 1e-12)\n        #expect(BoostTrainer.baseScore(plain, scalePosWeight: 1) == Double(plain.y.reduce(0, +)) / Double(plain.count))\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/CalibrationTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,58]],"header":{"lines":[1,9],"target":"VeilGardeTrainingTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1739,"scopes":[["S","CalibrationTests",null,"",16,17,[17,24],58,null,-1,0,"a"],["f","platt",[],"",18,19,[19,24],28,null,0,0,"a"],["f","threshold",[],"",30,31,[31,28],40,null,0,0,"a"],["f","contract",[],"",42,43,[43,27],57,null,0,0,"a"]],"old":"","new":"//\n//  CalibrationTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Platt reaches sklearn's optimum on tile-vote fractions (and sits within 2e-3 of the\n//        reference lbfgs fit), choose_operating_threshold is reproduced exactly, and the trainer's contract\n//        decodes under the strict validator bound to the sensor model's hash.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Sensor calibration\")\nstruct CalibrationTests {\n    @Test(\"Platt on the calibration partition matches sklearn\")\n    func platt() throws {\n        let f = try Fixture.json(\"platt_fixture.json\")\n        let frac = doubles(f[\"frac\"]), y = ints(f[\"y\"]), calib = ints(f[\"calibration\"])\n        let fit = Platt.fit(labels: calib.map { y[$0] }, probabilities: calib.map { frac[$0] })\n        let tight = f[\"tight\"] as! [String: Any], reference = f[\"reference\"] as! [String: Any]\n        #expect(abs(fit.coef - double(tight[\"coef\"])) < 1e-6)\n        #expect(abs(fit.intercept - double(tight[\"intercept\"])) < 1e-6)\n        #expect(abs(fit.coef - double(reference[\"coef\"])) < 2e-3)\n        #expect(abs(fit.intercept - double(reference[\"intercept\"])) < 2e-3)\n    }\n\n    @Test(\"the operating threshold is choose_operating_threshold's\")\n    func threshold() throws {\n        let f = try Fixture.json(\"platt_fixture.json\")\n        let y = ints(f[\"y\"]), held = ints(f[\"threshold_partition\"])\n        let selected = doubles(f[\"tight_selected\"])\n        let choice = try OperatingThreshold.choose(labels: held.map { y[$0] }, probabilities: selected, maxRealFPR: 0.10)\n        let expected = f[\"tight_operating\"] as! [String: Any]\n        #expect(choice.threshold == double(expected[\"threshold\"]))\n        #expect(choice.generatedRecall == double(expected[\"validation_generated_recall\"]))\n        #expect(throws: VeilGardeFailure.self) { try OperatingThreshold.choose(labels: [0, 0], probabilities: [0.9, 0.95], maxRealFPR: -1) }\n    }\n\n    @Test(\"the trainer's contract decodes bound to the sensor model\")\n    func contract() throws {\n        let f = try Fixture.json(\"platt_fixture.json\")\n        let frac = doubles(f[\"frac\"]), y = ints(f[\"y\"])\n        let samples = frac.indices.map { CalibrationTrainer.Sample(key: \"img\\($0)\", label: y[$0], fraction: frac[$0]) }\n        let sha = String(repeating: \"ab\", count: 32)\n        let (file, report) = try CalibrationTrainer.fit(samples, sensorModelSHA256: sha, sensorVariant: \"warp19\")\n        let data = try JSONCoding.prettyEncoder().encode(file)\n        let contract = try SensorCalibrationContract.decode(data, expectedModelSHA256: sha, expectedSensorVariant: \"warp19\")\n        #expect(contract.transform == report.calibration)\n        #expect(abs(Double(contract.decisionThreshold) - report.operating.threshold) < 1e-6)\n        #expect(contract.uncertainBand == 0.04)\n        #expect(report.fitImages.values.allSatisfy { $0 >= 25 })\n        #expect(report.crossFitFolds == 5)\n        #expect(throws: (any Error).self) { try SensorCalibrationContract.decode(data, expectedModelSHA256: String(repeating: \"cd\", count: 32), expectedSensorVariant: \"warp19\") }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/CombinerTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,96]],"header":{"lines":[1,9],"target":"VeilGardeTrainingTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1743,"scopes":[["S","CombinerTests",null,"",16,17,[17,21],96,null,-1,0,"a"],["f","fixture",[],"static",18,18,[18,50],18,null,0,8,"a"],["f","optional",["_"],"static",20,20,[20,49],20,null,0,8,"a"],["f","features",[],"",22,23,[23,27],32,null,0,0,"a"],["f","adjudication",[],"",34,35,[35,31],47,null,0,0,"a"],["f","samples",["_"],"",39,39,[39,59],41,null,4,4,"a"],["f","fit",[],"",49,50,[50,22],61,null,0,0,"a"],["f","sweepFallback",[],"",63,64,[64,32],77,null,0,0,"a"],["f","sweepShipped",[],"",79,80,[80,31],95,null,0,0,"a"]],"old":"","new":"//\n//  CombinerTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The combiner's columns equal atlas_combiner.features, its bounded fit reaches scipy's\n//        optimum, and the rescue sweep picks what the reference's picks: the fallback on the synthetic fit,\n//        and the shipped 0.5 on the shipped weights.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Stack combiner\")\nstruct CombinerTests {\n    static func fixture() throws -> [String: Any] { try Fixture.json(\"combiner_fixture.json\") }\n\n    static func optional(_ any: Any?) -> Double? { (any as? NSNumber)?.doubleValue }\n\n    @Test(\"the feature columns equal the reference's\")\n    func features() throws {\n        let f = try Self.fixture()\n        let base = doubles(f[\"base\"]), heads = (f[\"heads\"] as! [[NSNumber]]).map { $0.map(\\.doubleValue) }\n        let pair = (f[\"pair\"] as! [Any]).map(Self.optional), np = (f[\"np\"] as! [Any]).map(Self.optional)\n        let expected = (f[\"features\"] as! [[NSNumber]]).map { $0.map(\\.doubleValue) }\n        for i in base.indices {\n            let row = CombinerFeatures.row(base: base[i], heads: heads[i], pair: pair[i], noiseprint: np[i])\n            #expect(maxAbs(row, expected[i]) < 1e-12, \"row \\(i)\")\n        }\n    }\n\n    @Test(\"a combiner fitted with no art-pair head does not adjudicate, and one fitted beside it does\")\n    func adjudication() throws {\n        let f = try Self.fixture()\n        let base = doubles(f[\"base\"]), heads = (f[\"heads\"] as! [[NSNumber]]).map { $0.map(\\.doubleValue) }, y = ints(f[\"y\"])\n        let pair = (f[\"pair\"] as! [Any]).map(Self.optional), np = (f[\"np\"] as! [Any]).map(Self.optional)\n        func samples(_ withPair: Bool) -> [CombinerSample] {\n            base.indices.map { CombinerSample(id: \"row\\($0)\", label: y[$0], base: base[$0], heads: heads[$0], pair: withPair ? pair[$0] : nil, noiseprint: np[$0]) }\n        }\n        let (alone, _) = try CombinerTrainer.train(samples(false))\n        #expect(alone.pairAdjudicates == false && !alone.note.contains(\"art-pair\"))\n        #expect(try alone.combiner().pairAdjudicates == false)\n        let (beside, _) = try CombinerTrainer.train(samples(true))\n        #expect(beside.pairAdjudicates == true && beside.note.contains(\"art-pair\"))\n    }\n\n    @Test(\"the bounded fit reaches scipy's optimum\")\n    func fit() throws {\n        let f = try Self.fixture()\n        let features = (f[\"features\"] as! [[NSNumber]]).map { $0.map(\\.doubleValue) }\n        let y = ints(f[\"y\"]), n = f[\"train\"] as! Int\n        let (w0, w) = CombinerTrainer.fitWeights(features: Array(features.prefix(n)), labels: Array(y.prefix(n)), realsWeight: 3)\n        let tight = f[\"tight\"] as! [String: Any]\n        let tw = doubles(tight[\"w\"])\n        #expect(abs(w0 - double(tight[\"w0\"])) < 1e-4)\n        for j in [0, 1, 2, 3, 5] { #expect(abs(w[j] - tw[j]) < 1e-4, \"w[\\(j)] \\(w[j]) vs \\(tw[j])\") }\n        #expect(w[4] == 0)\n        #expect(w.allSatisfy { $0 >= 0 })\n    }\n\n    @Test(\"the rescue sweep falls back to 1.0 when no weight keeps every probe real\")\n    func sweepFallback() throws {\n        let f = try Self.fixture()\n        let final = f[\"final\"] as! [String: Any]\n        var w = doubles(final[\"w\"])\n        w[4] = 0\n        let (rescue, rows) = CombinerTrainer.chooseRescue(w0: double(final[\"w0\"]), w: w, settings: CombinerSettings())\n        #expect(rescue == 1.0)\n        let expected = f[\"sweep\"] as! [[String: Any]]\n        for (row, e) in zip(rows, expected) {\n            #expect(row.rescue == double(e[\"w_rescue\"]))\n            #expect(row.probesReal == e[\"user_reals_real\"] as! Int)\n            #expect(abs(row.maxProbe - double(e[\"max_p\"])) < 1e-12)\n        }\n    }\n\n    @Test(\"on the shipped weights the sweep picks the shipped 0.5\")\n    func sweepShipped() throws {\n        let f = try Self.fixture()\n        let w = [3.8205217946638634, 0.0, 0.0, 0.1966929563436263, 0.0, 0.8]\n        let (rescue, rows) = CombinerTrainer.chooseRescue(w0: -0.6754975033517225, w: w, settings: CombinerSettings())\n        #expect(rescue == double(f[\"deployed_chosen\"]))\n        #expect(rescue == 0.5)\n        let expected = f[\"deployed_sweep\"] as! [[String: Any]]\n        for (row, e) in zip(rows, expected) {\n            var ww = w\n            ww[4] = row.rescue\n            let mine = CombinerTrainer.probeScores(-0.6754975033517225, ww, CombinerProbe.userReals)\n            for (name, p) in e[\"p\"] as! [String: NSNumber] { #expect(abs(mine[name]! - p.doubleValue) < 1e-12, \"probe \\(name)\") }\n        }\n        let shipped = try CombinerFile(w0: -0.6754975033517225, wBase: w[0], wGen: Array(w[1...3]), wRescue: rescue, wNp: w[5], note: \"\").combiner()\n        #expect(shipped.wRescue == 0.5)\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/EngineTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,121]],"header":{"lines":[1,11],"target":"VeilGardeTrainingTests","what":[6,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1752,"scopes":[["S","EngineTests",null,"",18,19,[19,19],121,null,-1,0,"a"],["f","recipe",["_","id"],"",20,20,[20,74],28,null,0,0,"a"],["f","plan",[],"",30,31,[31,23],42,null,0,0,"a"],["f","refusals",[],"",44,45,[45,27],56,null,0,0,"a"],["f","train",[],"",58,59,[59,24],108,null,0,0,"a"],["f","warpAlone",[],"",110,111,[111,28],120,null,0,0,"a"]],"old":"","new":"//\n//  EngineTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A whole recipe through the engine on a synthetic work area: the plan reads without\n//        training, a refusal stops the run before a candidate exists, and the run writes a\n//        candidate bundle that verifies, whose warp model is its own sensor model with a\n//        calibration bound to it, whose fusion head keeps the parent's 940 trees byte for byte,\n//        and whose heads and combiner load as the detector loads them.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Training engine\", .serialized)\nstruct EngineTests {\n    func recipe(_ s: SyntheticArea, id: String = \"toy\") -> TrainingRecipe {\n        TrainingRecipe(id: id) {\n            Combiner()\n            WarpTileModel(dataset: s.dataset).trees(12).depth(3)\n            SensorCalibration()\n            FusionHead().warmStart(add: 3, eta: 0.03).allowMixedWarp(false)\n            for kind in [HeadKind.art, .blur, .human, .cgi, .artPair, .preview] { DinoHead(kind) }\n        }\n    }\n\n    @Test(\"the plan names every stage and touches nothing\")\n    func plan() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store)\n        let plan = try engine.plan(recipe(s))\n        #expect(plan.refusals.isEmpty, \"\\(plan.refusals)\")\n        #expect(plan.models.map(\\.model) == [\"warp-tile\", \"sensor-calibration\", \"fusion-head\", \"head:art\", \"head:blur\", \"head:human\", \"head:cgi\", \"head:art-pair\", \"head:preview\", \"combiner\"])\n        let warp = plan.models[0]\n        #expect(warp.stages.first?.stage == .tiles && warp.stages.first?.runs == false, \"the tiles are cached\")\n        #expect(plan.summary.contains(\"deployed: 12 trees, depth 3\"))\n        #expect(!FileManager.default.fileExists(atPath: plan.candidate.path))\n    }\n\n    @Test(\"a refusal stops the run before a candidate exists\")\n    func refusals() throws {\n        let s = try SyntheticArea.make(mixedWarp: true)\n        defer { s.remove() }\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store)\n        let bad = TrainingRecipe(id: \"bad\") { DinoHead(.semtile); FusionHead() }\n        let plan = try engine.plan(bad)\n        #expect(plan.refusals.count == 2, \"semtile has no tokens; the store mixes warp models\")\n        #expect(throws: VeilGardeFailure.self) { try engine.train(bad) }\n        #expect(!FileManager.default.fileExists(atPath: plan.candidate.path))\n        #expect(try engine.plan(TrainingRecipe(id: \"ok\") { FusionHead().allowMixedWarp() }).refusals.isEmpty)\n        #expect(throws: VeilGardeFailure.self) { try engine.plan(TrainingRecipe(id: \"a/b\") { Combiner() }) }\n    }\n\n    @Test(\"a full recipe writes a candidate bundle the detector can load\")\n    func train() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        var lines: [String] = []\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store) { if let l = $0.line { lines.append(l) } }\n        let outcome = try engine.train(recipe(s))\n        let c = outcome.candidate\n        try c.verify()\n        let parent = try ModelBundle.load(s.parent)\n\n        // The warp model is its own sensor model, and the calibration is bound to it.\n        let warp = try #require(c.manifest.artifact(.warpTile)), sensor = try #require(c.manifest.artifact(.warpMajoritySensor))\n        #expect(warp.sha256 == sensor.sha256 && warp.file == \"warp/warp_tile32.xgb.json\")\n        #expect(warp.sha256 != parent.sha256(.warpTile))\n        let model = try GBDTModel.load(c.url(.warpTile)!)\n        #expect(model.trees.count == 12 && model.featureNames == WarpFeatures.names)\n        let calibration = try Data(contentsOf: c.url(.sensorCalibration)!)\n        let contract = try SensorCalibrationContract.decode(calibration, expectedModelSHA256: warp.sha256, expectedSensorVariant: \"warp19\")\n        #expect(contract.transform == .cuts, \"the engine writes the fitted contract as two cuts on the vote\")\n\n        // The fusion head continues the parent's: 940 trees untouched, 3 appended, the parent recorded.\n        let fusion = try #require(c.manifest.artifact(.fusionHead))\n        #expect(fusion.parent == parent.sha256(.fusionHead))\n        let head = try GBDTModel.load(c.url(.fusionHead)!), before = try GBDTModel.load(parent.url(.fusionHead)!)\n        #expect(head.trees.count == before.trees.count + 3)\n        for i in 0..<before.trees.count { #expect(head.trees[i].raw == before.trees[i].raw) }\n\n        // Heads and the combiner load as the detector loads them.\n        for kind in [HeadKind.art, .blur, .human, .cgi, .artPair, .preview] {\n            let url = try #require(c.url(.head, head: kind))\n            #expect(url.path.hasSuffix(\"heads/\\(kind.rawValue)/head.json\"))\n            #expect(try LinearHead.load(url).coef.count == 384)\n            #expect(FileManager.default.fileExists(atPath: c.root.appendingPathComponent(\"heads/\\(kind.rawValue)/metrics.json\").path))\n        }\n        let combiner = try JSONDecoder().decode(StackCombiner.self, from: Data(contentsOf: c.url(.combiner)!))\n        #expect(combiner.wBase >= 0)\n        #expect(combiner.pairAdjudicates == true, \"this recipe trained an art-pair head, so its combiner adjudicates; the shipped recipe trains none\")\n        // What the recipe did not name is the parent's, byte for byte.\n        #expect(c.manifest.artifact(.head, head: .screenshot)?.sha256 == parent.sha256(.head, head: .screenshot))\n        #expect(c.manifest.artifact(.fusionReference)?.sha256 == parent.sha256(.fusionReference))\n        #expect(c.manifest.weights == parent.manifest.weights)\n        // The record of the run.\n        let runs = try String(contentsOf: c.root.appendingPathComponent(\"runs.jsonl\"), encoding: .utf8).split(separator: \"\\n\")\n        #expect(runs.count > 20)\n        #expect(lines.contains { $0.hasPrefix(\"candidate toy verified\") })\n        #expect(outcome.metrics.keys.sorted() == [\"combiner\", \"fusion-head\", \"head:art\", \"head:art-pair\", \"head:blur\", \"head:cgi\", \"head:human\", \"head:preview\", \"sensor-calibration\", \"warp-tile\"])\n        #expect(try JSONDecoder().decode(TrainingRecipe.self, from: Data(contentsOf: c.root.appendingPathComponent(\"recipe.json\"))) == recipe(s))\n        // A second run under the same id is refused.\n        #expect(throws: VeilGardeFailure.self) { try engine.train(recipe(s)) }\n    }\n\n    @Test(\"a warp model retrained without its calibration drops the parent's contract\")\n    func warpAlone() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store)\n        let r = TrainingRecipe(id: \"warp-only\") { WarpTileModel(dataset: s.dataset).trees(4).depth(2) }\n        #expect(try engine.plan(r).models[0].notes.contains { $0.contains(\"falls back to identity\") })\n        let c = try engine.train(r).candidate\n        #expect(c.manifest.artifact(.sensorCalibration) == nil)\n        try c.verify()\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,38]],"header":{"lines":[1,8],"target":"VeilGardeTrainingTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1758,"scopes":[["E","Fixture",null,"",13,13,[13,13],32,null,-1,0,"a",[]],["f","resource",["_"],"static",22,22,[22,48],22,null,0,8,"a"],["f","url",["_"],"static",24,24,[24,43],24,null,0,8,"a"],["f","json",["_"],"static",26,26,[26,61],28,null,0,0,"a"],["f","tensors",["_"],"static",30,30,[30,66],30,null,0,8,"a"],["f","floats",["_"],"",34,34,[34,36],34,null,-1,8,"a"],["f","doubles",["_"],"",35,35,[35,38],35,null,-1,8,"a"],["f","ints",["_"],"",36,36,[36,32],36,null,-1,8,"a"],["f","double",["_"],"",37,37,[37,35],37,null,-1,8,"a"],["f","maxAbs",["_","_"],"",38,38,[38,52],38,null,-1,8,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the training tests read: their committed fixtures (written once from the Python\n//        reference) and the shipped bundle's resources, by repo path.\n//\n\nimport Foundation\nimport VeilGardeCore\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static let resources = repoRoot.appendingPathComponent(\"Sources/VeilGardeInference/Resources\")\n\n    static func resource(_ name: String) -> URL { resources.appendingPathComponent(name) }\n\n    static func url(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeTrainingTests/Fixtures/\\(name)\") }\n\n    static func json(_ name: String) throws -> [String: Any] {\n        try JSONSerialization.jsonObject(with: Data(contentsOf: url(name))) as! [String: Any]\n    }\n\n    static func tensors(_ name: String) throws -> SafetensorsFile { try SafetensorsFile(url: url(name)) }\n\n}\n\nfunc floats(_ any: Any?) -> [Float] { (any as? [NSNumber])?.map { $0.floatValue } ?? [] }\nfunc doubles(_ any: Any?) -> [Double] { (any as? [NSNumber])?.map { $0.doubleValue } ?? [] }\nfunc ints(_ any: Any?) -> [Int] { (any as? [NSNumber])?.map { $0.intValue } ?? [] }\nfunc double(_ any: Any?) -> Double { (any as? NSNumber)?.doubleValue ?? .nan }\nfunc maxAbs(_ a: [Double], _ b: [Double]) -> Double { zip(a, b).map { abs($0 - $1) }.max() ?? 0 }\n"},{"path":"Tests/VeilGardeTrainingTests/LinkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,15]],"header":{"lines":[1,7],"target":"VeilGardeTrainingTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1768,"scopes":[["S","TrainingLinkTests",null,"",12,13,[13,25],15,null,-1,0,"a"],["f","reExportsCore",[],"",14,14,[14,31],14,null,0,8,"a"]],"old":"","new":"//\n//  LinkTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The module links and re-exports the layers below it.\n//\n\nimport Testing\nimport VeilGardeTraining\n\n@Suite(\"Training links\")\nstruct TrainingLinkTests {\n    @Test func reExportsCore() { #expect(!VeilGardeVersion.string.isEmpty) }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/LogisticTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,37]],"header":{"lines":[1,9],"target":"VeilGardeTrainingTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1770,"scopes":[["S","LogisticTests",null,"",15,16,[16,21],37,null,-1,0,"a"],["f","heads",["_"],"",17,18,[18,38],36,null,0,0,"a"]],"old":"","new":"//\n//  LogisticTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The sklearn-parity solvers. StandardScaler + LogisticNewton reach sklearn's optimum for\n//        the three head recipes (balanced C 0.5, unweighted C 0.5, unweighted C 1) within 1e-5,\n//        and sit within 2e-3 of the reference fits made at lbfgs's default tolerance.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeTraining\n\n@Suite(\"Logistic solvers\")\nstruct LogisticTests {\n    @Test(\"the head recipes reach sklearn's optimum\", arguments: [\"balanced_c05\", \"none_c05\", \"none_c1\"])\n    func heads(_ name: String) throws {\n        let t = try Fixture.tensors(\"lr_fixture.safetensors\")\n        let x = try t.float32(\"x\"), y = try t.float32(\"y\").map(Double.init)\n        let d = 48, n = y.count\n        let c = (try Fixture.json(\"lr_fixture.json\")[\"cases\"] as! [[String: Any]]).first { $0[\"name\"] as! String == name }!\n        let all = Array(0..<n)\n        let scaler = StandardScaler.fit(x, d: d, rows: all)\n        #expect(maxAbs(scaler.mean, doubles(c[\"mean\"])) < 1e-9)\n        #expect(maxAbs(scaler.scale, doubles(c[\"scale\"])) < 1e-9)\n        #expect(scaler.scale[5] == 1)\n        let z = scaler.transform(x, d: d, rows: all)\n        let fit = LogisticNewton.fit(x: z, y: y, d: d, C: double(c[\"C\"]), classWeight: c[\"class_weight\"] as! String == \"balanced\" ? .balanced : .none)\n        #expect(maxAbs(fit.coef, doubles(c[\"coef\"])) < 1e-5, \"\\(name): coef\")\n        #expect(abs(fit.intercept - double(c[\"intercept\"])) < 1e-5, \"\\(name): intercept\")\n        #expect(maxAbs(fit.coef, doubles(c[\"reference_coef\"])) < 2e-3, \"\\(name): distance to the reference lbfgs fit\")\n        let p = (0..<n).map { fit.probability(z[($0 * d)..<(($0 + 1) * d)]) }\n        #expect(maxAbs(p, doubles(c[\"p\"])) < 1e-6)\n        #expect(fit.coef[5] == 0)\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/MLXGate.swift","status":"added","lang":"swift","hunks":[[1,0,1,21]],"header":{"lines":[1,10],"target":"VeilGardeTrainingTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1772,"scopes":[["S","TrainingMLXSuites",null,"",20,21,[21,25],21,null,-1,8,"a"]],"old":"","new":"//\n//  MLXGate.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX suites run one at a time and only when asked: VEILGARDE_MLX_TESTS=1 (or\n//        FRIGATE_MLX_TESTS=1). Every GPU suite in this target nests under TrainingMLXSuites, which\n//        is serialized; run the targets with `swift test --no-parallel` too, so two MLX workloads\n//        never overlap.\n//\n\nimport Foundation\nimport Testing\n\nlet mlxTests: Bool = {\n    let env = ProcessInfo.processInfo.environment\n    return env[\"VEILGARDE_MLX_TESTS\"] == \"1\" || env[\"FRIGATE_MLX_TESTS\"] == \"1\"\n}()\n\n@Suite(\"Training: MLX, one suite at a time\", .enabled(if: mlxTests), .serialized)\nstruct TrainingMLXSuites {}\n"},{"path":"Tests/VeilGardeTrainingTests/MetricsTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,34]],"header":{"lines":[1,7],"target":"VeilGardeTrainingTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1773,"scopes":[["S","MetricsTests",null,"",13,14,[14,20],34,null,-1,0,"a"],["f","sklearn",[],"",15,16,[16,26],24,null,0,0,"a"],["f","edges",[],"",26,27,[27,17],33,null,0,0,"a"]],"old":"","new":"//\n//  MetricsTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: AUC (ties averaged, weighted or not) and log loss equal sklearn's on a tied score.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeTraining\n\n@Suite(\"Metrics\")\nstruct MetricsTests {\n    @Test(\"AUC and log loss equal sklearn's, ties and weights included\")\n    func sklearn() throws {\n        let fixture = try Fixture.json(\"boost_hist.json\")\n        let m = fixture[\"metrics\"] as! [String: Any]\n        let p = floats(m[\"p\"]), w = floats(m[\"w\"])\n        let y = try Fixture.tensors(\"boost_hist.safetensors\").float32(\"y_val\")\n        #expect(abs(Metrics.auc(p, y) - double(m[\"auc\"])) < 1e-12)\n        #expect(abs(Metrics.auc(p, y, weights: w) - double(m[\"auc_weighted\"])) < 1e-9)\n        #expect(abs(Metrics.logloss(p, y) - double(m[\"logloss\"])) < 1e-9)\n    }\n\n    @Test(\"a missing class gives NaN; the operating point counts the band as inconclusive\")\n    func edges() {\n        #expect(Metrics.auc([0.1, 0.2], [1, 1]).isNaN)\n        let op = Metrics.operatingPoint([0.1, 0.55, 0.9, 0.7], [0, 0, 1, 0], threshold: 0.56, band: 0.04)\n        #expect(op.inconclusiveRate == 0.25)\n        #expect(op.realFalsePositiveRate == 1.0 / 3.0)\n        #expect(op.generatedRecall == 1)\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/NoiseprintTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,285]],"header":{"lines":[1,12],"target":"VeilGardeTrainingTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1776,"scopes":[["E","NoiseprintFixture",null,"",23,23,[23,23],53,null,-1,0,"a",[]],["f","image",["width","height","_"],"static",25,25,[25,88],31,[24,24],0,0,"a"],["f","noise",["width","height","seed"],"static",33,33,[33,72],36,null,0,0,"a"],["f","folder",["_","_","count"],"static",39,39,[39,81],46,[38,38],0,0,"a"],["f","temporary",[],"static",48,48,[48,42],52,null,0,0,"a"],["S","NoiseprintDataTests",null,"",55,56,[56,27],198,null,-1,0,"a"],["f","split",[],"",57,58,[58,24],81,null,5,0,"a"],["f","exclusion",[],"",83,84,[84,28],110,null,5,0,"a"],["f","folder",["_","count"],"",87,87,[87,65],92,null,7,4,"a"],["f","adoption",[],"",112,113,[113,20],125,null,5,0,"a"],["f","evaluation",["_","_","anchor"],"",114,114,[114,101],117,null,9,4,"a"],["f","sampler",[],"",127,128,[128,26],155,null,5,0,"a"],["f","levels",[],"",157,158,[158,25],166,null,5,0,"a"],["f","recipeFile",[],"",168,169,[169,29],175,null,5,0,"a"],["f","plan",[],"",177,178,[178,23],197,null,5,0,"a"],["X","TrainingMLXSuites",null,"",200,200,[200,28],285,null,-1,0,"a"],["S","NoiseprintOnGPU",null,"",201,202,[202,27],284,null,15,0,"a"],["f","patches",["_","seed"],"static",203,203,[203,64],206,null,16,0,"a"],["f","fold",[],"",208,209,[209,27],230,null,16,0,"a"],["f","bayar",[],"",232,233,[233,21],243,null,16,0,"a"],["f","shipped",[],"",247,247,[247,30],255,null,16,0,"a"],["f","trains",[],"",257,258,[258,29],283,null,16,0,"a"]],"old":"","new":"//\n//  NoiseprintTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The noiseprint trainer. On the CPU: the reference split (disjoint, seeded, three to one per\n//        family), the patch sampler (seeded, blank patches dropped, bytes equal to the gray\n//        plane), the recompression levels (JPEG and HEIC on this Mac), the recipe table and the\n//        engine's plan. On the GPU: a trained-form net and its folded file compute the same\n//        P(camera); the Bayar projection holds; the shipped net loads into the trained form and\n//        folds back to its own bytes; and a few epochs on toy patches lower the loss.\n//\n\nimport CoreGraphics\nimport Foundation\nimport MLX\nimport MLXNN\nimport Testing\nimport VeilGardeCore\nimport VeilGardeLens\n@testable import VeilGardeTraining\n\nenum NoiseprintFixture {\n    /// An RGB image whose pixel (x, y) is `value(x, y)` in 0…255 on every channel.\n    static func image(width: Int, height: Int, _ value: (Int, Int) -> UInt8) -> CGImage {\n        var px = [UInt8](repeating: 255, count: width * height * 4)\n        for y in 0..<height { for x in 0..<width { let v = value(x, y); px[(y * width + x) * 4] = v; px[(y * width + x) * 4 + 1] = v; px[(y * width + x) * 4 + 2] = v } }\n        let ctx = CGContext(data: &px, width: width, height: height, bitsPerComponent: 8, bytesPerRow: width * 4, space: CGColorSpaceCreateDeviceRGB(),\n                            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!\n        return ctx.makeImage()!\n    }\n\n    static func noise(width: Int, height: Int, seed: UInt64) -> CGImage {\n        var rng = SplitMix64(seed: seed)\n        return image(width: width, height: height) { _, _ in UInt8(truncatingIfNeeded: rng.next() >> 56) }\n    }\n\n    /// A folder of empty files with image extensions (listing never decodes).\n    static func folder(_ root: URL, _ name: String, count: Int) throws -> String {\n        let dir = root.appendingPathComponent(name, isDirectory: true)\n        try FileManager.default.createDirectory(at: dir.appendingPathComponent(\"sub\"), withIntermediateDirectories: true)\n        for i in 0..<count { FileManager.default.createFile(atPath: dir.appendingPathComponent(i % 3 == 0 ? \"sub/img_\\(i).png\" : \"img_\\(i).jpg\").path, contents: Data()) }\n        FileManager.default.createFile(atPath: dir.appendingPathComponent(\"._img_0.jpg\").path, contents: Data())\n        FileManager.default.createFile(atPath: dir.appendingPathComponent(\"notes.txt\").path, contents: Data())\n        return dir.path\n    }\n\n    static func temporary() throws -> URL {\n        let url = FileManager.default.temporaryDirectory.appendingPathComponent(\"veilgarde-noiseprint-\\(UUID().uuidString)\", isDirectory: true)\n        try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)\n        return url\n    }\n}\n\n@Suite(\"Noiseprint trainer: data\")\nstruct NoiseprintDataTests {\n    @Test(\"the reference split: camera then each family from one seeded stream, disjoint, three to one\")\n    func split() throws {\n        let root = try NoiseprintFixture.temporary()\n        defer { try? FileManager.default.removeItem(at: root) }\n        var sources = NoiseprintSources(camera: try NoiseprintFixture.folder(root, \"camera\", count: 12),\n                                        negatives: [NoiseprintFamily(\"a\", try NoiseprintFixture.folder(root, \"a\", count: 10)),\n                                                    NoiseprintFamily(\"b\", try NoiseprintFixture.folder(root, \"b\", count: 6)),\n                                                    NoiseprintFamily(\"empty\", root.appendingPathComponent(\"nowhere\").path)])\n        sources.cameraTrain = 8\n        sources.perFamily = 8\n        let s = try sources.split()\n        #expect(NoiseprintSources.list(sources.camera).count == 12, \"resource forks and other files are left out; subfolders are walked\")\n        #expect(s.cameraTrain.count == 8 && s.cameraTest.count == 4)\n        #expect(Set(s.cameraTrain).isDisjoint(with: s.cameraTest))\n        #expect(s.counts[\"a\"] == [10, 6, 2] && s.counts[\"b\"] == [6, 6, 0] && s.counts[\"empty\"] == [0, 0, 0])\n        #expect(s.negativeTrain.count == 12)\n        #expect(s.negativeTest.map(\\.family) == [\"a\", \"b\", \"empty\"])\n        #expect(try sources.split() == s, \"the same folders and seed give the same split\")\n        var reseeded = sources\n        reseeded.seed = 1\n        #expect(try reseeded.split() != s)\n        var tooFew = sources\n        tooFew.cameraTrain = 12\n        #expect(throws: VeilGardeFailure.self) { try tooFew.split() }\n    }\n\n    @Test(\"an excluded file leaves every folder, by path and by content, and a family added last keeps the others' splits\")\n    func exclusion() throws {\n        let root = try NoiseprintFixture.temporary()\n        defer { try? FileManager.default.removeItem(at: root) }\n        func folder(_ name: String, count: Int) throws -> String {\n            let dir = root.appendingPathComponent(name, isDirectory: true)\n            try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n            for i in 0..<count { try Data(\"\\(name)-\\(i)\".utf8).write(to: dir.appendingPathComponent(\"img_\\(i).jpg\")) }\n            return dir.path\n        }\n        let camera = try folder(\"camera\", count: 12), a = try folder(\"a\", count: 10), forged = try folder(\"forged\", count: 8)\n        let anchor = forged + \"/img_3.jpg\"\n        try FileManager.default.copyItem(atPath: anchor, toPath: a + \"/copy_of_anchor.jpg\")\n        var before = NoiseprintSources(camera: camera, negatives: [NoiseprintFamily(\"a\", a)])\n        before.cameraTrain = 8\n        before.perFamily = 8\n        var after = before\n        after.negatives.append(NoiseprintFamily(\"forged\", forged))\n        let s = try after.split(excluding: [anchor])\n        #expect(s.excluded.map { URL(fileURLWithPath: $0).lastPathComponent } == [\"copy_of_anchor.jpg\", \"img_3.jpg\"], \"the copy under another name goes too\")\n        #expect(s.counts[\"a\"] == [10, 6, 2] && s.counts[\"forged\"] == [7, 6, 1])\n        let every = s.cameraTrain + s.cameraTest + s.negativeTrain + s.negativeTest.flatMap(\\.urls)\n        #expect(!every.contains { $0.lastPathComponent == \"copy_of_anchor.jpg\" || $0.path.hasSuffix(\"/forged/img_3.jpg\") })\n        let first = try before.split(excluding: [anchor])\n        #expect(s.cameraTrain == first.cameraTrain && s.cameraTest == first.cameraTest && s.negativeTest[0].urls == first.negativeTest[0].urls,\n                \"a family appended last does not move the families before it\")\n        #expect(try after.split().counts[\"forged\"] == [8, 6, 2], \"nothing is excluded unless asked\")\n    }\n\n    @Test(\"adoption: the anchor under 0.5, the pooled AUC within 0.005 of the parent's, the photoreal AUC at least the parent's\")\n    func adoption() {\n        func evaluation(_ all: Double, _ photoreal: Double, anchor: Double?) -> NoiseprintEvaluation {\n            NoiseprintEvaluation(levels: [.init(level: .native, auc: [\"ALL\": all, \"photoreal\": photoreal], cameraMean: 0.8, familyMean: [:])],\n                                 cameraImages: 10, familyImages: [:], anchor: anchor)\n        }\n        let parent = evaluation(0.940, 0.80, anchor: 0.43)\n        #expect(NoiseprintAdoption.judge(candidate: evaluation(0.936, 0.80, anchor: 0.2), parent: parent).passed, \"within 0.005, and equal on photoreal\")\n        let anchorReadsCamera = NoiseprintAdoption.judge(candidate: evaluation(0.96, 0.9, anchor: 0.578), parent: parent)\n        #expect(!anchorReadsCamera.passed && anchorReadsCamera.rules.map(\\.passed) == [false, true, true], \"the 2026-10-19 retrain's failure\")\n        #expect(NoiseprintAdoption.judge(candidate: evaluation(0.934, 0.9, anchor: 0.2), parent: parent).rules.map(\\.passed) == [true, false, true])\n        #expect(NoiseprintAdoption.judge(candidate: evaluation(0.95, 0.79, anchor: 0.2), parent: parent).rules.map(\\.passed) == [true, true, false])\n        #expect(!NoiseprintAdoption.judge(candidate: evaluation(0.95, 0.9, anchor: nil), parent: parent).passed, \"no anchor score, no adoption\")\n    }\n\n    @Test(\"the sampler draws seeded patches from the gray plane and drops blank ones\")\n    func sampler() throws {\n        var settings = PatchSettings()\n        settings.scaleAugment = false\n        settings.levels = [.native]\n        let cg = NoiseprintFixture.noise(width: 300, height: 200, seed: 3)\n        var a = PythonRandom(seed: 5), b = PythonRandom(seed: 5)\n        let (first, level) = try PatchSampler.patches(cg, count: 4, settings: settings, rng: &a)\n        let (second, _) = try PatchSampler.patches(cg, count: 4, settings: settings, rng: &b)\n        #expect(level == .native)\n        #expect(first.count == 4 && first == second)\n        #expect(first.allSatisfy { $0.count == 128 * 128 })\n        let (gray, w, _) = try #require(NoiseprintLens.grayBytes(cg))\n        // Every patch is a window of the gray plane.\n        let patch = first[0]\n        var found = false\n        for y in 0...(200 - 128) where !found {\n            for x in 0...(w - 128) where gray[y * w + x] == patch[0] && gray[y * w + x + 1] == patch[1] {\n                if (0..<128).allSatisfy({ r in Array(gray[((y + r) * w + x)..<((y + r) * w + x + 128)]) == Array(patch[(r * 128)..<(r * 128 + 128)]) }) { found = true; break }\n            }\n        }\n        #expect(found)\n        let flat = NoiseprintFixture.image(width: 200, height: 200) { _, _ in 90 }\n        var c = PythonRandom(seed: 5)\n        #expect(try PatchSampler.patches(flat, count: 4, settings: settings, rng: &c).patches.isEmpty, \"blank patches are dropped, not redrawn\")\n        let small = NoiseprintFixture.noise(width: 100, height: 100, seed: 4)\n        var d = PythonRandom(seed: 5)\n        #expect(try PatchSampler.patches(small, count: 4, settings: settings, rng: &d).patches.isEmpty)\n    }\n\n    @Test(\"the recompression levels encode on this Mac and keep the size\")\n    func levels() throws {\n        #expect(ImageCodec.canEncode(.jpeg) && ImageCodec.canEncode(.heic))\n        let cg = NoiseprintFixture.noise(width: 160, height: 144, seed: 9)\n        for level in NoiseprintLevel.allCases {\n            let out = try level.apply(cg)\n            #expect(out.width == 160 && out.height == 144, \"\\(level)\")\n        }\n        #expect(NoiseprintLevel.heic75.recipeName == \"webp75\")\n    }\n\n    @Test(\"a recipe file's [noiseprint] table\")\n    func recipeFile() throws {\n        let recipe = try RecipeFile.parse(\"id = \\\"np\\\"\\n[noiseprint]\\nepochs = 2\\nper_family = 40\\nseed = 7\\ncache_patches = false\\n\")\n        guard case .noiseprint(let n)? = recipe.models.first else { Issue.record(\"no noiseprint model\"); return }\n        #expect(n.settings.epochs == 2 && n.settings.sources.perFamily == 40 && n.settings.seed == 7 && !n.settings.cachePatches)\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"np\\\"\\n[noiseprint]\\nlr = 1\\n\") }\n        #expect(TrainingRecipe(id: \"x\") { NoiseprintModel(); Combiner() }.ordered.map(\\.name) == [\"combiner\", \"noiseprint\"])\n    }\n\n    @Test(\"the plan reads the folders and names the stages without training\")\n    func plan() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        let root = try NoiseprintFixture.temporary()\n        defer { try? FileManager.default.removeItem(at: root) }\n        var sources = NoiseprintSources(camera: try NoiseprintFixture.folder(root, \"camera\", count: 12),\n                                        negatives: [NoiseprintFamily(\"a\", try NoiseprintFixture.folder(root, \"a\", count: 10))])\n        sources.cameraTrain = 8\n        sources.perFamily = 8\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store)\n        let plan = try engine.plan(TrainingRecipe(id: \"np\") { NoiseprintModel().sources(sources).epochs(2) })\n        #expect(plan.refusals.isEmpty, \"\\(plan.refusals)\")\n        let model = try #require(plan.models.first)\n        #expect(model.model == \"noiseprint\")\n        #expect(model.stages.map(\\.stage) == [.data, .patches, .fit, .evaluate, .write])\n        #expect(model.stages[1].runs, \"nothing is cached yet\")\n        #expect(plan.summary.contains(\"2 epochs\"))\n        sources.cameraTrain = 20\n        #expect(try engine.plan(TrainingRecipe(id: \"np\") { NoiseprintModel().sources(sources) }).refusals.count == 1)\n    }\n}\n\nextension TrainingMLXSuites {\n    @Suite(\"Noiseprint on the GPU\", .serialized)\n    struct NoiseprintOnGPU {\n        static func patches(_ n: Int, seed: UInt64) -> MLXArray {\n            var rng = SplitMix64(seed: seed)\n            return MLXArray((0..<(n * 128 * 128)).map { _ in Float(rng.next() >> 40) / Float(1 << 24) }, [n, 128, 128, 1])\n        }\n\n        @Test(\"the folded file computes what the trained form computes\")\n        func fold() throws {\n            MLXRandom.seed(11)\n            let net = NoiseprintTrainNet()\n            net.projectBayar()\n            var stats: [String: MLXArray] = [:]\n            for (i, c) in NoiseprintTrainNet.channels.dropFirst().enumerated() {\n                stats[\"bn\\(i).running_mean\"] = MLXRandom.normal([c]) * 0.1\n                stats[\"bn\\(i).running_var\"] = MLXRandom.uniform(low: 0.5, high: 2.0, [c])\n                stats[\"bn\\(i).weight\"] = MLXRandom.uniform(low: 0.5, high: 1.5, [c])\n                stats[\"bn\\(i).bias\"] = MLXRandom.normal([c]) * 0.1\n            }\n            net.update(parameters: ModuleParameters.unflattened(stats))\n            net.train(false)\n            let x = Self.patches(6, seed: 2)\n            let trained = sigmoid(net(x)).mean().item(Float.self)\n            let weights = try net.folded()\n            let folded = try NoiseprintNet(weights: weights.mapValues { MLXArray($0.values, $0.shape) })\n            #expect(abs(folded.score(x) - trained) <= 1e-5, \"folded \\(folded.score(x)) against trained \\(trained)\")\n            #expect(weights.keys.sorted() == [\"conv0.bias\", \"conv0.weight\", \"conv1.bias\", \"conv1.weight\", \"conv2.bias\", \"conv2.weight\",\n                                              \"conv3.bias\", \"conv3.weight\", \"linear.bias\", \"linear.weight\"])\n            #expect(weights[\"conv1.weight\"]?.shape == [24, 3, 3, 8] && weights[\"linear.weight\"]?.shape == [1, 48])\n        }\n\n        @Test(\"the Bayar projection: centre −1, the other taps of each filter summing to 1\")\n        func bayar() {\n            MLXRandom.seed(3)\n            let net = NoiseprintTrainNet()\n            net.projectBayar()\n            let w = net.conv0.weight.asArray(Float.self)       // [8, 5, 5, 1]\n            for f in 0..<8 {\n                let taps = Array(w[(f * 25)..<(f * 25 + 25)])\n                #expect(taps[12] == -1)\n                #expect(abs(taps.enumerated().filter { $0.offset != 12 }.map(\\.element).reduce(0, +) - 1) < 1e-5)\n            }\n        }\n\n        @Test(\"the shipped net loads into the trained form and folds back to its own bytes\",\n              .enabled(if: Backbone.shipped(.noiseprint) != nil))\n        func shipped() throws {\n            let url = try #require(Backbone.shipped(.noiseprint))\n            let arrays = try loadArrays(url: url)\n            let net = try NoiseprintTrainNet.unfolded(arrays)\n            let x = Self.patches(5, seed: 8)\n            let original = try NoiseprintNet(weights: arrays).score(x)\n            #expect(abs(sigmoid(net(x)).mean().item(Float.self) - original) <= 1e-5)\n            #expect(try NoiseprintTrainNet.file(try net.folded()) == Data(contentsOf: url), \"the round trip changes the file's bytes\")\n        }\n\n        @Test(\"a few epochs on toy patches lower the loss and fold into a working net\")\n        func trains() throws {\n            // Camera = fine noise, everything else = smooth ramps with a little noise.\n            var pixels: [UInt8] = [], labels: [UInt8] = []\n            var rng = SplitMix64(seed: 21)\n            for i in 0..<96 {\n                let camera = i % 2 == 0\n                for y in 0..<128 { for x in 0..<128 {\n                    let jitter = Int(rng.next() >> 61)\n                    pixels.append(camera ? UInt8(truncatingIfNeeded: rng.next() >> 56) : UInt8(min(255, (x + y) + jitter)))\n                } }\n                labels.append(camera ? 1 : 0)\n            }\n            var settings = NoiseprintSettings()\n            settings.epochs = 4\n            settings.batch = 32\n            let (net, losses) = NoiseprintTrainer.train(PatchSet(patch: 128, pixels: pixels, labels: labels), settings: settings)\n            #expect(losses.count == 4)\n            #expect(losses.last! < losses.first!, \"\\(losses)\")\n            let folded = try NoiseprintNet(weights: try net.folded().mapValues { MLXArray($0.values, $0.shape) })\n            var noiseValues = [Float](repeating: 0, count: 128 * 128)\n            for i in 0..<noiseValues.count { noiseValues[i] = Float(rng.next() >> 56) / 255 }\n            let noise = MLXArray(noiseValues, [1, 128, 128, 1])\n            let rampValues: [Float] = (0..<(128 * 128)).map { (i: Int) -> Float in Float(i % 128 + i / 128) / 255 }\n            let ramp = MLXArray(rampValues, [1, 128, 128, 1])\n            #expect(folded.score(noise) > folded.score(ramp))\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/PythonRandomTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,38]],"header":{"lines":[1,8],"target":"VeilGardeTrainingTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1798,"scopes":[["S","PythonRandomTests",null,"",14,15,[15,25],38,null,-1,0,"a"],["f","sequences",[],"",16,17,[17,28],37,null,0,0,"a"]],"old":"","new":"//\n//  PythonRandomTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The CPython `random.Random` port draws Python's exact sequences: 32- and 64-bit words,\n//        random(), randrange and shuffle, for small and multi-word seeds.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeTraining\n\n@Suite(\"CPython random\")\nstruct PythonRandomTests {\n    @Test(\"every recorded sequence matches CPython 3.12\")\n    func sequences() throws {\n        let cases = try Fixture.json(\"python_random.json\")[\"cases\"] as! [[String: Any]]\n        #expect(cases.count == 5)\n        for c in cases {\n            let seed = UInt64(c[\"seed\"] as! String)!\n            var r = PythonRandom(seed: seed)\n            #expect((0..<6).map { _ in Int(r.getrandbits(32)) } == ints(c[\"bits32\"]), \"seed \\(seed)\")\n            r = PythonRandom(seed: seed)\n            #expect((0..<6).map { _ in r.random() } == doubles(c[\"random\"]), \"seed \\(seed)\")\n            r = PythonRandom(seed: seed)\n            var a = Array(0..<10), b = Array(0..<37)\n            r.shuffle(&a); r.shuffle(&b)\n            #expect(a == ints(c[\"shuffle10\"]), \"seed \\(seed)\")\n            #expect(b == ints(c[\"shuffle37\"]), \"seed \\(seed)\")\n            r = PythonRandom(seed: seed)\n            let bounds = (c[\"randbelow_n\"] as! [String]).map { Int($0)! }\n            #expect(bounds.map { r.randbelow($0) } == (c[\"randbelow\"] as! [String]).map { Int($0)! }, \"seed \\(seed)\")\n            r = PythonRandom(seed: seed)\n            #expect((0..<3).map { _ in r.getrandbits(64) } == (c[\"bits64\"] as! [String]).map { UInt64($0)! }, \"seed \\(seed)\")\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/RecipeTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,82]],"header":{"lines":[1,9],"target":"VeilGardeTrainingTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1800,"scopes":[["S","RecipeTests",null,"",16,17,[17,19],82,null,-1,0,"a"],["f","builder",[],"",20,21,[21,26],40,null,0,0,"a"],["f","shipped",[],"",42,43,[43,19],47,null,0,0,"a"],["f","toml",[],"",49,50,[50,23],81,null,0,0,"a"]],"old":"","new":"//\n//  RecipeTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The recipe DSL: the builder takes `if` and `for`, modifiers return changed copies, the\n//        engine's order is the dependency order, recipes round-trip as JSON, and recipe.toml\n//        reads into the same values (refusing what it does not know).\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Training recipes\")\nstruct RecipeTests {\n    let dataset = URL(fileURLWithPath: \"/data/final_mixed\")\n\n    @Test(\"the builder, the modifiers and the dependency order\")\n    func builder() throws {\n        let withPair = true\n        let recipe = TrainingRecipe(id: \"r\") {\n            Combiner().realsWeight(2)\n            for kind in [HeadKind.art, .blur] { DinoHead(kind).regularization(C: 0.25) }\n            if withPair { DinoHead(.artPair) }\n            FusionHead().warmStart(add: 10)\n            SensorCalibration().band(0.05)\n            WarpTileModel(dataset: dataset).shape(.v18).trees(50)\n        }\n        #expect(recipe.ordered.map(\\.name) == [\"warp-tile\", \"sensor-calibration\", \"fusion-head\", \"head:art\", \"head:blur\", \"head:art-pair\", \"combiner\"])\n        guard case .warpTile(let w) = recipe.ordered[0] else { Issue.record(\"no warp\"); return }\n        #expect(w.params.trees == 50 && w.params.maxDepth == 4 && w.params.earlyStoppingRounds == 30)\n        guard case .head(let pair) = recipe.ordered[5] else { Issue.record(\"no pair\"); return }\n        #expect(pair.settings.classWeight == .none && pair.settings.fireThreshold == nil && !pair.settings.admission)\n        let base = DinoHead(.human)\n        #expect(base.regularization(C: 2).settings.C == 2 && base.settings.C == 0.5)\n        let data = try JSONEncoder().encode(recipe)\n        #expect(try JSONDecoder().decode(TrainingRecipe.self, from: data) == recipe)\n    }\n\n    @Test(\"the shipped preset trains every model the store can reproduce\")\n    func shipped() {\n        let names = TrainingRecipe.shipped(id: \"s\", dataset: dataset).ordered.map(\\.name)\n        #expect(names == [\"warp-tile\", \"sensor-calibration\", \"fusion-head\", \"head:art\", \"head:blur\", \"head:human\", \"head:cgi\", \"head:preview\", \"combiner\"])\n        #expect(WarpShape.deployed.params == BoostParams(trees: 200, maxDepth: 8, eta: 0.1, subsample: 0.8, colsampleByTree: 0.8, seed: 0))\n    }\n\n    @Test(\"recipe.toml reads into the same recipe\")\n    func toml() throws {\n        let text = \"\"\"\n        id = \"weekly\"   # a comment\n        [warp]\n        dataset = \"/data/final_mixed\"\n        shape = \"v18\"\n        sample_per_label = 40\n        [calibration]\n        band = 0.05\n        [fusion]\n        mode = \"warm\"\n        add = 20\n        [heads]\n        kinds = [\"art\", \"art-pair\"]\n        [combiner]\n        reals_weight = 2.0\n        \"\"\"\n        let recipe = try RecipeFile.parse(text)\n        let expected = TrainingRecipe(id: \"weekly\") {\n            WarpTileModel(dataset: dataset).shape(.v18).sample(perLabel: 40)\n            SensorCalibration().band(0.05)\n            FusionHead().warmStart(add: 20, eta: 0.03)\n            DinoHead(.art)\n            DinoHead(.artPair)\n            Combiner().realsWeight(2)\n        }\n        #expect(recipe == expected)\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[warp]\\ndataset = \\\"/d\\\"\\ncolour = 1\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[optimizer]\\nlr = 1\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"[heads]\\nkinds = [\\\"art\\\"]\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[heads]\\nkinds = [\\\"faces\\\"]\") }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/ResearchTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,104]],"header":{"lines":[1,12],"target":"VeilGardeTrainingTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1804,"scopes":[["S","ResearchTests",null,"",19,20,[20,21],104,null,-1,0,"a"],["f","noise",["_","seed"],"static",21,21,[21,57],24,null,0,0,"a"],["f","paired",[],"",26,27,[27,18],38,null,0,0,"a"],["f","calibration",[],"",40,41,[41,30],56,null,0,0,"a"],["f","study",[],"",58,59,[59,24],103,null,0,0,"a"]],"old":"","new":"//\n//  ResearchTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The pruning study's arithmetic and its whole run. A paired comparison's AUC is Metrics'\n//        AUC, identical scorings differ by exactly nothing, a better scoring's interval sits above\n//        zero, and a seed gives the same interval twice. The Platt layer's call is a cut on the raw\n//        tile vote for every vote a 256-tile grid can cast. On a synthetic work area whose only\n//        label signal is FR, the study finds what it should: FR and its group cost AUC, no other\n//        feature costs a tenth as much, alone or together, and every part reports its rows.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Research: the pruning study\")\nstruct ResearchTests {\n    static func noise(_ n: Int, seed: UInt64) -> [Float] {\n        var rng = SplitMix64(seed: seed)\n        return (0..<n).map { _ in Float(rng.unit()) }\n    }\n\n    @Test(\"a paired comparison: Metrics' AUC, zero for identical scorings, an interval above zero for a better one, the same twice\")\n    func paired() {\n        let n = 400\n        let labels = (0..<n).map { Float($0 % 2) }\n        let ref = Self.noise(n, seed: 1).map { ($0 * 8).rounded() / 8 }          // ties\n        #expect(abs((RankedScores(ref, labels).auc(nil) ?? 0) - Metrics.auc(ref, labels)) < 1e-12)\n        let same = PairedComparison.measure(reference: ref, variant: ref, labels: labels, resamples: 200, seed: 0, call: { $0 > 0.5 ? \"g\" : \"r\" })\n        #expect(same.delta == 0 && same.low == 0 && same.high == 0 && same.changedCalls == 0 && same.spansZero)\n        let better = zip(Self.noise(n, seed: 2), labels).map { $0 * 0.6 + $1 * 0.4 }\n        let c = PairedComparison.measure(reference: ref, variant: better, labels: labels, resamples: 200, seed: 0, call: { $0 > 0.5 ? \"g\" : \"r\" })\n        #expect(c.delta > 0.2 && c.low > 0 && !c.spansZero && c.low <= c.delta && c.delta <= c.high)\n        #expect(c == PairedComparison.measure(reference: ref, variant: better, labels: labels, resamples: 200, seed: 0, call: { $0 > 0.5 ? \"g\" : \"r\" }))\n    }\n\n    @Test(\"Garde's Platt contract is two cuts on the raw tile vote, the shipped ones, for every vote a 256-tile grid can cast\")\n    func calibration() throws {\n        let sha = \"516119c92d364dda3dba41dcfc42e06edf0f42e45efd3b54c44ab620f7eefe3d\"\n        let platt = try SensorCalibrationContract(sensorVariant: \"warp19\", sensorModelSHA256: sha, transform: .platt,\n                                                  plattPayload: SensorPlattPayload(coef: 0.48908749922126266, intercept: -0.09094760943132153),\n                                                  decisionThreshold: Float(0.6298664647384551), uncertainBand: 0.04)\n        let data = try Data(contentsOf: Fixture.resources.appendingPathComponent(\"warp_sensor_calibration.json\"))\n        let shipped = try SensorCalibrationContract.decode(data, expectedModelSHA256: sha, expectedSensorVariant: \"warp19\")\n        let votes = (0...256).map { Float($0) / 256 }\n        let e = PruningStudy.equivalence(platt, votes: votes)\n        #expect(e.agreeing == e.images && e.images == 257)\n        #expect(e.rawReal < e.rawThreshold && e.rawThreshold < e.rawGenerated)\n        #expect(abs(e.rawThreshold - 0.781) < 0.001, \"T 0.6299 is a vote of 78.1%\")\n        #expect(shipped.transform == .cuts && shipped.cuts == SensorCuts(realAtOrBelow: e.rawReal, generatedAtOrAbove: e.rawGenerated))\n        #expect(votes.allSatisfy { shipped.prediction(for: shipped.calibratedProbability($0)) == platt.prediction(for: platt.calibratedProbability($0)) })\n        #expect(PruningStudy.equivalence(shipped, votes: votes).agreeing == 257)\n    }\n\n    @Test(\"on a synthetic area the study finds FR, and every part reports its rows\")\n    func study() throws {\n        let synthetic = try SyntheticArea.make(images: 400)\n        defer { synthetic.remove() }\n        var s = PruningSettings()\n        s.resamples = 60\n        s.warpParams = BoostParams(trees: 30, maxDepth: 3, eta: 0.3, subsample: 0.8, colsampleByTree: 0.8, seed: 0)\n        s.warpStages = [5, 15]\n        s.warpDepths = [2]\n        s.fusionTrees = 10\n        s.fusionStages = [5]\n        s.fusionDepths = [2]\n        s.shippedFusionStages = [100]\n        s.seedControls = [1]\n        let bundle = try ModelBundle.load(synthetic.parent)\n        let inputs = PruningStudy.Inputs(tiles: synthetic.area.root.appendingPathComponent(\"store/tiles/dataset\"), store: synthetic.store, bundle: bundle)\n        let report = try PruningStudy.run(inputs, settings: s, parts: Set(PruningPart.allCases))\n        let warp = try #require(report.warp)\n        #expect(warp.trees.count == 2 && warp.depths.count == 1 && warp.permuted.count == 6 && warp.groupsDropped.count == 6 && warp.featuresDropped.count == 19)\n        let fr = try #require(warp.featuresDropped.first { $0.name == \"without FR\" })\n        #expect(fr.verdict == \"costs AUC\" && fr.primary.delta < -0.1, \"FR carries the label\")\n        #expect(warp.groupsDropped.first { $0.name == \"without residual\" }?.verdict == \"costs AUC\")\n        #expect(warp.permuted.first { $0.name == \"residual\" }?.verdict == \"costs AUC\")\n        let others = warp.featuresDropped.filter { $0.name != \"without FR\" }\n        // 58 test images: a refit's own noise is about ±0.01 AUC, so the others are held to a tenth of FR's cost.\n        #expect(others.allSatisfy { $0.primary.delta > fr.primary.delta / 10 }, \"no other feature carries anything\")\n        #expect(warp.droppedTogether.map { $0.primary.delta > fr.primary.delta / 10 } ?? true)\n        #expect(warp.scores.map(\\.name) == [\"plain mean\", \"median\", \"tile vote\"])\n        #expect(warp.seeds.count == 1 && warp.groupsTogether.map(\\.name) == [\"without mirror, seam, cfa\"])\n        #expect(warp.groupsTogether[0].primary.delta > fr.primary.delta / 10, \"the three groups carry nothing here\")\n        #expect(warp.calibration.agreeing == warp.calibration.images && warp.calibration.images == warp.testImages)\n        #expect(abs(warp.shippedGain.values.reduce(0, +) - 1) < 1e-9 && warp.shippedGain.count == 19)\n        let fusion = try #require(report.fusion)\n        #expect(fusion.trees.count == 1 && fusion.depths.count == 1 && fusion.inputs.map(\\.name)\n                == [\"without warp\", \"without capture\", \"without sharpness\", \"DINOv2 alone\", \"without DINOv2\"])\n        #expect(fusion.trainRows + fusion.testRows == fusion.rows && fusion.testRows > 0 && fusion.shippedPermuted.count == 4)\n        #expect(fusion.seeds.count == 1 && fusion.inputsTogether.map(\\.name) == [\"without sharp and warp\"])\n        let stack = try #require(report.stack)\n        #expect(stack.variants.count == 9 && stack.realRows + stack.generatedRows == stack.rows)\n        for v in stack.variants {\n            #expect((stack.movedToGenerated[v.name] ?? -1) + (stack.movedToReal[v.name] ?? -1) == v.primary.changedCalls, \"\\(v.name)\")\n            #expect((stack.shippedRight[v.name] ?? -1) >= 0 && (stack.shippedRight[v.name] ?? 0) <= v.primary.changedCalls, \"\\(v.name)\")\n        }\n        #expect(report.rules.count == 5 && Set(report.seconds.keys) == [\"warp\", \"fusion\", \"stack\"])\n        _ = try JSONCoding.prettyEncoder().encode(report)\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/SplitTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,89]],"header":{"lines":[1,8],"target":"VeilGardeTrainingTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1809,"scopes":[["S","SplitTests",null,"",15,16,[16,18],89,null,-1,0,"a"],["f","raSplit",[],"",17,18,[18,26],25,null,0,0,"a"],["f","oneClassFallback",[],"",27,28,[28,28],43,null,0,0,"a"],["f","manifest",[],"",45,46,[46,27],62,null,0,0,"a"],["f","finalMixed",[],"",64,65,[65,29],76,null,0,0,"a"],["f","folds",[],"",78,79,[79,17],88,null,0,0,"a"]],"old":"","new":"//\n//  SplitTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The head split, draw for draw (source-disjoint with ≥ 4 sources, by id otherwise), the\n//        manifest's stem partition, final_mixed's CSV, and the stratified folds.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Splits and manifests\")\nstruct SplitTests {\n    @Test(\"HeadSplit.heads equals atlas_heads_store.py's split\")\n    func raSplit() throws {\n        let cases = try Fixture.json(\"head_split.json\")[\"cases\"] as! [[String: Any]]\n        for c in cases {\n            let split = HeadSplit.heads(ids: c[\"ids\"] as! [String], sources: c[\"sources\"] as! [String])\n            #expect(split.isTest == (c[\"test\"] as! [Bool]))\n            #expect(split.basis.rawValue == c[\"basis\"] as! String)\n        }\n    }\n\n    @Test(\"a source split that leaves a class out falls back to the id split\")\n    func oneClassFallback() {\n        // Every generated row comes from one source; that source is not among the test sources.\n        let sources = [\"civitai\", \"a\", \"b\", \"c\", \"d\", \"e\", \"f\", \"g\"]\n        var ids: [String] = [], src: [String] = [], labels: [Int] = []\n        for k in 0..<400 { ids.append(\"id\\(k)\"); src.append(sources[k % sources.count]); labels.append(src.last == \"civitai\" ? 1 : 0) }\n        let plain = HeadSplit.heads(ids: ids, sources: src)\n        let checked = HeadSplit.heads(ids: ids, sources: src, labels: labels)\n        let testHoldsBoth = Set(zip(labels, checked.isTest).filter { $0.1 }.map(\\.0)).count == 2\n        if Set(zip(labels, plain.isTest).filter { $0.1 }.map(\\.0)).count == 2 {\n            #expect(checked == plain)\n        } else {\n            #expect(checked.basis == .idsAfterOneClassSources)\n            #expect(testHoldsBoth)\n            #expect(checked.isTest == HeadSplit.byIDs(ids).isTest)\n        }\n    }\n\n    @Test(\"a manifest partitions by stem, 70/15/15, and round-trips its bytes\")\n    func manifest() throws {\n        let records = (0..<2000).map { ImageRecord(path: \"x/\\($0).jpg\", label: $0 % 2, stem: \"stem\\($0 / 2)\") }\n        let m = ImageManifest(records: records, root: URL(fileURLWithPath: \"/tmp\")).withSplits()\n        for k in stride(from: 0, to: 2000, by: 2) { #expect(m.records[k].split == m.records[k + 1].split, \"a stem's variants share a partition\") }\n        let train = Double(m.records(in: .train).count) / 2000\n        #expect(abs(train - 0.70) < 0.05)\n        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-manifest-\\(UUID().uuidString)\")\n        defer { try? FileManager.default.removeItem(at: dir) }\n        let url = dir.appendingPathComponent(\"dataset.jsonl\")\n        try m.write(to: url)\n        let back = try ImageManifest.load(url)\n        #expect(back.records == m.records)\n        #expect(back.sha256 == m.sha256)\n        let sample = m.sample(perLabel: 10, seed: 1)\n        #expect(sample.count == 20)\n        #expect(sample == m.sample(perLabel: 10, seed: 1))\n    }\n\n    @Test(\"final_mixed's CSV converts, quotes and all\")\n    func finalMixed() throws {\n        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-fm-\\(UUID().uuidString)\")\n        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n        defer { try? FileManager.default.removeItem(at: dir) }\n        let csv = \"dest_name,class,source_pool,tag,scored_verdict,src_path\\r\\niphone_real_00000.jpeg,real,iphone,iphone,real,\\\"/a,b/IMG.jpeg\\\"\\r\\nagvr_ai_00001.png,generated,agvr_gen,fill,generated,/x.png\\r\\n\"\n        try csv.write(to: dir.appendingPathComponent(\"manifest.csv\"), atomically: true, encoding: .utf8)\n        let m = try ImageManifest.finalMixed(dir)\n        #expect(m.records.map(\\.path) == [\"real/iphone_real_00000.jpeg\", \"generated/agvr_ai_00001.png\"])\n        #expect(m.records.map(\\.label) == [0, 1])\n        #expect(m.records.map(\\.stem) == [\"iphone_real_00000\", \"agvr_ai_00001\"])\n        #expect(m.records[1].pool == \"agvr_gen\")\n    }\n\n    @Test(\"hash folds are stratified and order-free\")\n    func folds() {\n        let keys = (0..<100).map { \"k\\($0)\" }, labels = (0..<100).map { $0 < 30 ? 1 : 0 }\n        let fold = HashFolds.stratified(keys: keys, labels: labels, k: 5, salt: \"t\")\n        for f in 0..<5 {\n            #expect(keys.indices.filter { fold[$0] == f && labels[$0] == 1 }.count == 6)\n            #expect(keys.indices.filter { fold[$0] == f && labels[$0] == 0 }.count == 14)\n        }\n        let reversed = HashFolds.stratified(keys: keys.reversed(), labels: labels.reversed(), k: 5, salt: \"t\")\n        #expect(Array(reversed.reversed()) == fold)\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/Synthetic.swift","status":"added","lang":"swift","hunks":[[1,0,1,107]],"header":{"lines":[1,9],"target":"VeilGardeTrainingTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[[40,"The store"],[85,"The dataset and its cached tiles"]],"first":1815,"scopes":[["S","SyntheticArea",null,"",15,15,[15,21],107,null,-1,0,"a"],["f","make",["images","mixedWarp"],"static",22,22,[22,89],36,null,0,0,"a"],["f","remove",[],"",38,38,[38,18],38,null,0,8,"a"],["f","writeStore",["_","mixedWarp"],"static",42,42,[42,69],83,null,0,0,"a"],["f","gauss",[],"",44,44,[44,30],47,null,3,4,"a"],["f","writeDataset",["_","images","cache"],"static",87,87,[87,73],106,null,0,0,"a"]],"old":"","new":"//\n//  Synthetic.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A throwaway work area for the engine's tests: a copy of the shipped bundle as the parent,\n//        a seeded features-only store with every category the recipes read, and a dataset whose\n//        tiles are already cached, so a full recipe trains without the GPU or a single image.\n//\n\nimport Foundation\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\nstruct SyntheticArea {\n    let root: URL\n    let area: WorkArea\n    let parent: URL\n    let store: URL\n    let dataset: URL\n\n    static func make(images: Int = 800, mixedWarp: Bool = false) throws -> SyntheticArea {\n        let root = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-engine-\\(UUID().uuidString)\", isDirectory: true)\n        let fm = FileManager.default\n        try fm.createDirectory(at: root, withIntermediateDirectories: true)\n        // The parent: the shipped bundle's resources, copied.\n        let parent = root.appendingPathComponent(\"parent\", isDirectory: true)\n        try fm.copyItem(at: Fixture.resources, to: parent)\n        let area = WorkArea(root: root.appendingPathComponent(\"area\", isDirectory: true))\n        let store = area.root.appendingPathComponent(\"store/shards\", isDirectory: true)\n        try fm.createDirectory(at: store, withIntermediateDirectories: true)\n        try writeStore(store, mixedWarp: mixedWarp)\n        let dataset = root.appendingPathComponent(\"toy/dataset.jsonl\")\n        try writeDataset(dataset, images: images, cache: area.root.appendingPathComponent(\"store/tiles/dataset\", isDirectory: true))\n        return SyntheticArea(root: root, area: area, parent: parent, store: store, dataset: dataset)\n    }\n\n    func remove() { try? FileManager.default.removeItem(at: root) }\n\n    // MARK: The store\n\n    static func writeStore(_ directory: URL, mixedWarp: Bool) throws {\n        var rng = SplitMix64(seed: 7)\n        func gauss() -> Float {\n            let u = max(1e-12, rng.unit()), v = rng.unit()\n            return Float((-2 * log(u)).squareRoot() * cos(2 * .pi * v))\n        }\n        let sources = [\"civitai\", \"commons_native\", \"wikimedia\", \"inat\", \"hf_faces\", \"openverse\", \"mj_v6\"]\n        let plan: [(category: String, label: Int, count: Int)] = [\n            (\"art\", 1, 150), (\"art\", 0, 100), (\"blur\", 1, 100), (\"blur\", 0, 80), (\"human\", 1, 120), (\"human\", 0, 200),\n            (\"cgi\", 1, 80), (\"cgi\", 0, 60), (\"preview\", 1, 60), (\"preview\", 0, 60), (\"photo\", 0, 220),\n        ]\n        let categoryIndex = [\"art\": 0, \"blur\": 1, \"human\": 2, \"cgi\": 3, \"preview\": 4, \"photo\": 5]\n        for (shardName, newGen) in [(\"base_a\", false), (\"scrape_20260101\", true)] {\n            var rows: [FeatureRow] = []\n            var columns: [FeatureColumn: [Float]] = Dictionary(uniqueKeysWithValues: FeatureColumn.allCases.map { ($0, [Float]()) })\n            var serial = 0\n            for p in plan where !newGen || p.label == 1 {\n                let n = newGen ? p.count / 3 : p.count\n                for _ in 0..<n {\n                    serial += 1\n                    let id = ContentHash.sha1Hex(Data(\"\\(shardName)-\\(serial)\".utf8))\n                    let golden = !newGen && p.category == \"photo\" && serial % 7 == 0\n                    let path = golden && serial % 21 == 0 ? \"/pools/bsky/\\(serial).jpg\" : \"/pools/\\(p.category)/\\(serial).jpg\"\n                    rows.append(FeatureRow(id: id, path: path, label: p.label, category: p.category, source: sources[serial % sources.count],\n                                           nsfw: serial % 53 == 0, golden: golden, warpModel: mixedWarp && newGen ? \"0123456789ab\" : nil))\n                    let c = categoryIndex[p.category]!\n                    var norm = (0..<384).map { _ in gauss() }\n                    if p.label == 1 { for j in (c * 10)..<(c * 10 + 10) { norm[j] += 1.6 } }\n                    var fusion = (0..<384).map { _ in gauss() }\n                    if p.label == 1 { for j in 0..<12 { fusion[j] += 1.0 } }\n                    columns[.dinoNorm]! += norm\n                    columns[.dinoFusion]! += fusion\n                    let present: Float = p.label == 0 && serial % 3 == 0 ? 1 : 0\n                    columns[.cap]! += [Float(rng.unit() * 60), 1, present, 2000, Float(rng.unit() * 10), 0.5, 0.5, 0.5, 0]\n                    columns[.warp]!.append(Float(min(1, max(0, (p.label == 1 ? 0.6 : 0.4) + 0.15 * Double(gauss())))))\n                    columns[.sharp]! += [Float(rng.unit() * 40), Float(rng.unit() * 40), Float(rng.unit() * 2)]\n                    columns[.noiseprint]!.append(Float(min(1, max(0, (p.label == 0 ? 0.6 : 0.3) + 0.2 * Double(gauss())))))\n                }\n            }\n            try FeatureShard(name: shardName, rows: rows, columns: columns).write(to: directory)\n        }\n    }\n\n    // MARK: The dataset and its cached tiles\n\n    static func writeDataset(_ url: URL, images: Int, cache: URL) throws {\n        var rng = SplitMix64(seed: 11)\n        let records = (0..<images).map { i in ImageRecord(path: \"img/\\(i).png\", label: i % 2, stem: String(format: \"img_%04d\", i)) }\n        let manifest = ImageManifest(records: records, root: url.deletingLastPathComponent()).withSplits()\n        try manifest.write(to: url)\n        var tileImages: [TileImage] = [], features: [Float] = [], texture: [Float] = []\n        for r in manifest.records {\n            tileImages.append(TileImage(stem: r.stem, path: r.path, label: r.label, split: r.split!, pool: nil, tag: nil, rows: 2, cols: 2,\n                                        start: texture.count, width: 64, height: 64))\n            for _ in 0..<4 {\n                var row = (0..<WarpFeatures.count).map { _ in Float(rng.unit()) }\n                row[0] = Float(rng.unit()) * 0.6 + (r.label == 1 ? 0.35 : 0)      // FR carries the label\n                features += row\n                texture.append(Float(0.2 + rng.unit()))\n            }\n        }\n        try FileManager.default.createDirectory(at: cache, withIntermediateDirectories: true)\n        try TileShard(name: \"tiles_0000\", images: tileImages, features: features, texture: texture,\n                      metadata: [\"manifest_sha256\": manifest.sha256]).write(to: cache)\n    }\n}\n"}]};
